export type ExtraText = { [K in keyof typeof ROWS]: string };

const LANGS: Language[] = ['tr', 'en', 'it', 'de', 'ru', 'hi'];

export const EXTRA_TEXT = LANGS.reduce((acc, lang, i) => {
  acc[lang] = Object.fromEntries(Object.entries(ROWS).map(([k, row]) => [k, row[i]])) as ExtraText;
  return acc;
}, {} as Record<Language, ExtraText>);
